source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker_axis = marker_index = None
    for r, row in enumerate(grid):
        if row and all(v == 2 for v in row):
            marker_axis, marker_index = 0, r
            break
    if marker_axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                marker_axis, marker_index = 1, c
                break
    if marker_axis is None:
        return out
    bg = Counter(v for row in grid for v in row if v != 2).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not pts:
        return out
    color = grid[pts[0][0]][pts[0][1]]
    if marker_axis == 0:
        top = min(r for r, c in pts)
        bottom = max(r for r, c in pts)
        if bottom < marker_index:
            dr = marker_index - 1 - bottom
            line_r = top + dr - 1
        else:
            dr = marker_index + 1 - top
            line_r = bottom + dr + 1
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r + dr][c] = color
        if 0 <= line_r < h:
            out[line_r] = [8] * w
    else:
        left = min(c for r, c in pts)
        right = max(c for r, c in pts)
        if right < marker_index:
            dc = marker_index - 1 - right
            line_c = left + dc - 1
        else:
            dc = marker_index + 1 - left
            line_c = right + dc + 1
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r][c + dc] = color
        if 0 <= line_c < w:
            for r in range(h):
                out[r][line_c] = 8
    return out
'''
